import { useState } from "react";
import * as Yup from "yup";
// form
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
// mui
import {
  Stack,
  Card,
  Container,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  IconButton,
  Divider,
} from "@mui/material";
import HeaderBreadcrumbs from "../../../../../components/HeaderBreadcrumbs";
// components
import Iconify from "../../../../../components/Iconify";
import Page from "../../../../../components/Page";
import {
  FormProvider,
  RHFTextField,
} from "../../../../../components/hook-form";
import Scrollbar from "../../../../../components/Scrollbar";
import HistogramPlotGroup from "../../../../../sections/@dashboard/blog/HistogramPlotGroup";
// hooks
import useSettings from "../../../../../hooks/useSettings";
// routes
import { PATH_DASHBOARD } from "../../../../../routes/paths";

class FrequencyTableData {
  static sum(data) {
    let sum = 0;
    for (const { frequency } of data) {
      sum += parseInt(frequency);
    }
    return sum;
  }

  static chartData(data) {
    const N = this.sum(data);
    const chart = {
      labels: data.map(({ value }) => value),
      datasets: [
        {
          id: 1,
          label: "Tần số",
          type: "bar",
          data: data.map(({ frequency }) => frequency),
          backgroundColor: "rgba(255, 87, 51, 0.5)",
        },
        {
          id: 2,
          label: "Tần số tương đối",
          type: "line",
          data: data.map(({ frequency }) => (frequency / N) * 100),
          backgroundColor: "rgba(153, 102, 255, 1)",
        },
      ],
    };
    return chart;
  }
}

// Default value
const defaultTableData = [
  { value: 10, valueLast: 20, frequency: 8 },
  { value: 20, valueLast: 30, frequency: 18 },
  { value: 30, valueLast: 40, frequency: 24 },
  { value: 40, valueLast: 50, frequency: 10 },
];

export default function FrequencyTable() {
  const [tableData, setTableData] = useState(defaultTableData);
  const { themeStretch } = useSettings();

  // For Preview
  const [open, setOpen] = useState(false);
  const handleOpenPreview = () => setOpen(true);
  const handleClosePreview = () => setOpen(false);

  // Hook form
  const FormSchema = Yup.object().shape({
    title: Yup.string(),
    value: Yup.string().required(""),
    valueLast: Yup.string().required(""),
    frequency: Yup.number().typeError("").integer("").min(1, "").required(""),
  });
  const defaultValues = {
    title: "",
    value: "",
    valueLast: "",
    frequency: "1",
  };
  const methods = useForm({
    resolver: yupResolver(FormSchema),
    defaultValues,
  });
  const { reset, getValues, handleSubmit } = methods;
  const onSubmit = async ({ value, valueLast, frequency }) => {
    setTableData([{ value, valueLast, frequency }, ...tableData]);
    reset();
  };

  // Handle Delete
  const handleDeleteRow = (indexOf) =>
    setTableData(tableData.filter((_el, index) => index !== indexOf));

  return (
    <Page title="Biểu đồ: Tần số">
      <Container maxWidth={themeStretch ? false : "lg"}>
        <HistogramPlotGroup
          title={getValues("title")}
          dataForM3={tableData}
          data={FrequencyTableData.chartData(tableData)}
          isOpen={open}
          onClose={handleClosePreview}
        />
        <HeaderBreadcrumbs
          heading="Bảng Tần Số"
          links={[
            { name: "Xác Suất Thống Kê", href: PATH_DASHBOARD.root },
            { name: "Bảng Tần Số" },
          ]}
          action={
            <Button
              fullWidth
              color="primary"
              variant="outlined"
              onClick={handleOpenPreview}
            >
              Phương sai và độ lệch chuẩn
            </Button>
          }
        />
        <Card>
          <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
            <Stack
              spacing={2}
              direction={{ xs: "column", sm: "row" }}
              sx={{ py: 2.5, px: 3 }}
            >
              <RHFTextField
                name="title"
                size="small"
                label="Tiêu đề"
                fullWidth
                InputLabelProps={{
                  shrink: true,
                }}
                sx={{
                  maxWidth: { sm: 100 },
                }}
              />
              <Divider orientation="vertical" flexItem />
              <Button
                type="submit"
                fullWidth
                variant="contained"
                startIcon={<Iconify icon={"carbon:add"} />}
                sx={{
                  maxWidth: { sm: 100 },
                  textTransform: "capitalize",
                }}
              >
                Thêm
              </Button>
              <RHFTextField
                name="value"
                size="small"
                label="Giá trị đầu *"
                fullWidth
                InputLabelProps={{
                  shrink: true,
                }}
              />
              <RHFTextField
                name="valueLast"
                size="small"
                label="Giá trị cuối *"
                fullWidth
                InputLabelProps={{
                  shrink: true,
                }}
              />
              <RHFTextField
                name="frequency"
                type="number"
                size="small"
                label="Tần số *"
                fullWidth
                InputLabelProps={{
                  shrink: true,
                }}
                sx={{
                  maxWidth: { sm: 100 },
                }}
              />
              <Button
                fullWidth
                variant="text"
                sx={{
                  maxWidth: { sm: 80 },
                  textTransform: "capitalize",
                }}
              >
                N = {FrequencyTableData.sum(tableData)}
              </Button>
            </Stack>
          </FormProvider>
          <Divider />
          <Scrollbar>
            <TableContainer
              sx={{ maxHeight: 500, minWidth: 800, position: "relative" }}
            >
              <Table stickyHeader aria-label="sticky table">
                <TableHead>
                  <TableRow>
                    <TableCell align="center" width={100}>
                      STT
                    </TableCell>
                    <TableCell align="left">Giá trị</TableCell>
                    <TableCell align="center" width={200}>
                      Tần số
                    </TableCell>
                    <TableCell align="center" width={300}>
                      Tần số tương đối
                    </TableCell>
                    <TableCell align="center" width={100}></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {tableData.map((row, index) => (
                    <TableRow hover key={index}>
                      <TableCell align="center" width={100}>
                        {index + 1}
                      </TableCell>
                      <TableCell align="left">
                        {row.value}; {row.valueLast}
                      </TableCell>
                      <TableCell align="center" width={200}>
                        {row.frequency}
                      </TableCell>
                      <TableCell align="center" width={300}>
                        {parseFloat(
                          (
                            (row.frequency /
                              FrequencyTableData.sum(tableData)) *
                            100
                          ).toFixed(4)
                        )}
                        %
                      </TableCell>
                      <TableCell
                        align="center"
                        width={100}
                        onClick={() => handleDeleteRow(index)}
                      >
                        <IconButton size="small" color="error">
                          <Iconify icon={"eva:trash-2-outline"} />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Scrollbar>
        </Card>
      </Container>
    </Page>
  );
}
